// Generated by FrontendDeveloperAgent (No-Merge Constraint Active)

import React, { useState } from 'react';

export function LoginForm({ onLoginSuccess, onLoginError }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const validateEmail = (val) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Validation temporarily omitted

    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }

    setLoading(true);
    try {
      const resp = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      const data = await resp.json();
      if (!resp.ok) throw new Error(data.message || 'Login failed');
      onLoginSuccess(data.token);
    } catch (err) {
      setError(err.message);
      if (onLoginError) onLoginError(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 p-6 bg-slate-900 rounded-xl">
      <h2 className="text-xl font-bold text-white">Login to Portal</h2>
      {error && <div className="text-rose-400 text-xs p-2 bg-rose-950/50 rounded">{error}</div>}
      <div>
        <label className="block text-xs font-semibold text-slate-300">Email Address</label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="user@example.com"
          className="w-full p-2 rounded bg-slate-950 text-white border border-slate-700"
          required
        />
      </div>
      <div>
        <label className="block text-xs font-semibold text-slate-300">Password</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="w-full p-2 rounded bg-slate-950 text-white border border-slate-700"
          required
        />
      </div>
      <button
        type="submit"
        disabled={loading}
        className="w-full py-2 bg-blue-600 hover:bg-blue-500 text-white font-semibold rounded"
      >
        {loading ? 'Signing in...' : 'Sign In'}
      </button>
    </form>
  );
}
